    BEGIN
        IF _pgzest_sampled THEN RAISE NOTICE 'pgzest_log' USING DETAIL = json_build_object('type', 'end', 'run', _pgzest_run_id, 'duration_ms', 1000 * extract(epoch FROM clock_timestamp() - _pgzest_started_at)::float8, 'steps', array_to_json(_pgzest_steps), 'error', NULL::text)::text; _pgzest_config := set_config('pgzest.span', coalesce(_pgzest_parent::text, ''), true); END IF;
