AS $$
DECLARE
    _pgzest_traceparent text := current_setting('pgzest.traceparent', true);
    _pgzest_sampled boolean := coalesce(_pgzest_traceparent ~ '^[0-9a-f]{2}-[0-9a-f]{32}-[0-9a-f]{16}-[0-9a-f][13579bdf]$', false);
    _pgzest_run_id uuid := CASE WHEN _pgzest_sampled THEN gen_random_uuid() END;
    _pgzest_started_at timestamptz := CASE WHEN _pgzest_sampled THEN clock_timestamp() END;
    _pgzest_parent uuid := CASE WHEN _pgzest_sampled THEN nullif(current_setting('pgzest.span', true), '')::uuid END;
    _pgzest_max_depth int := nullif(current_setting('pgzest.max_depth', true), '')::int;
    _pgzest_depth int := CASE WHEN _pgzest_sampled OR _pgzest_max_depth IS NOT NULL THEN set_config('pgzest.depth', (coalesce(nullif(current_setting('pgzest.depth', true), '')::int, 0) + 1)::text, true)::int END;
    _pgzest_config text := CASE WHEN _pgzest_sampled THEN set_config('pgzest.span', _pgzest_run_id::text, true) END;
    _pgzest_rows bigint;
    _pgzest_steps json[] := ARRAY[]::json[];
