BEGIN
    IF _pgzest_depth > _pgzest_max_depth THEN
        RAISE EXCEPTION 'pgzest: % called at depth %, beyond pgzest.max_depth', 'orders_award_loyalty_fn', _pgzest_depth USING ERRCODE = '54001';
    END IF;
    IF _pgzest_sampled THEN
        RAISE NOTICE 'pgzest_log' USING DETAIL = json_build_object('type', 'start', 'run', _pgzest_run_id, 'routine', 'orders_award_loyalty_fn', 'parent', _pgzest_parent, 'depth', _pgzest_depth, 'traceparent', CASE WHEN _pgzest_parent IS NULL THEN left(_pgzest_traceparent, 512) END, 'started_at', _pgzest_started_at)::text;
    END IF;

    UPDATE customers
    SET loyalty_points = loyalty_points + loyalty_points_of(NEW.id)
