CREATE TRIGGER orders_award_loyalty
AFTER UPDATE OF status ON orders
FOR EACH ROW WHEN ((((new.status = 'served') AND (old.status IS DISTINCT FROM 'served')) AND (new.customer_id IS NOT NULL)))
EXECUTE FUNCTION orders_award_loyalty_fn();

